/**
 * @file OutboxEvent.cs
 * @brief OutboxEvent entity (schema only in this release).
 */

namespace CSCN73030_26F_Sec1_ProjectV_Group_6.Server.Domain;

/// <summary>
/// Transactional outbox row for integration events (Staff.Onboarded, Staff.Terminated).
/// Schema only in this release; nothing publishes to Azure Service Bus yet.
/// </summary>
public class OutboxEvent
{
    /// <summary>Event id, set by the writer (not generated by the database).</summary>
    public Guid EventId { get; set; }

    /// <summary>Event name, e.g. "Staff.Onboarded".</summary>
    public string EventType { get; set; } = "";

    /// <summary>Version of the payload's schema.</summary>
    public int SchemaVersion { get; set; }

    /// <summary>Event body as JSON.</summary>
    public string PayloadJson { get; set; } = "";

    /// <summary>When the event happened, UTC.</summary>
    public DateTime OccurredAtUtc { get; set; }

    /// <summary>When it was published, or null while waiting.</summary>
    public DateTime? PublishedAtUtc { get; set; }
}
